<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {api} from './api';
import {ui} from './ui-copy';
import {locale} from './i18n';
const props=defineProps<{query:string;canManage:boolean}>();
const ruleName=(rule:string)=>({AUTH_FAILURES:th.value?'ยืนยันตัวตนผิดซ้ำ':'Repeated authentication failures',PORT_SCAN:th.value?'หลายพอร์ตถูกปฏิเสธ':'Multiple denied ports',WEB_PROBES:th.value?'ร้องขอไฟล์สำคัญซ้ำ':'Repeated sensitive path probes',IDS_SIGNATURE:th.value?'IDS ตรวจพบ signature':'IDS signature match'}[rule]??rule);
const th=computed(()=>locale.value==='th-TH');
type Case={id:number;status:string;agent:string;agentId:number;ip:string;actor:string;rule:string;explanation:string;owner:string|null;resolutionNote:string|null;evidenceCount:number;firstLogId:number;lastLogId:number};
const rows=ref<Case[]>([]),error=ref(''),busy=ref(false),truncated=ref(false),editing=ref<Case|null>(null),note=ref(''),owner=ref('');
const evidence=ref<{id:number;events:Array<{id:number;event:string;occurredAt:string;actor:string|null;result:string|null;detailsJson:string}>;truncated:boolean}|null>(null);
let evidenceGeneration=0;
async function journey(id:number){const current=++evidenceGeneration;error.value='';try{const r=await api<Omit<NonNullable<typeof evidence.value>,'id'>>(`/api/threats/cases/${id}/evidence`);if(current===evidenceGeneration)evidence.value={id,...r};}catch(e){if(current===evidenceGeneration)error.value=String(e);}}
let generation=0;
async function load(){const current=++generation;error.value='';try{const r=await api<{cases:Case[];truncated:boolean}>(`/api/threats/cases?${props.query}`);if(current===generation){rows.value=r.cases;truncated.value=r.truncated;}}catch(e){if(current===generation){rows.value=[];error.value=e instanceof Error?e.message:String(e);}}}
async function save(status:string){if(!editing.value)return;busy.value=true;error.value='';try{await api(`/api/findings/${editing.value.id}`,{method:'PUT',body:JSON.stringify({status,owner:owner.value,resolutionNote:note.value})});editing.value=null;await load();}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
watch(()=>props.query,()=>{editing.value=null;evidence.value=null;evidenceGeneration++;void load();},{immediate:true});
</script>
<template><details class="panel threat-cases"><summary>{{th?'เคสที่เกี่ยวข้อง':'Related cases'}} ({{rows.length}}{{truncated?'+':''}})</summary><p>{{th?'กรองตามเครื่อง IP และช่วงเวลาที่ตรวจพบ ไม่ใช้ตัวกรองชนิด Log รับทราบไม่ใช่ปิดเคส เมื่อปิดแล้วต้องมีหลักฐานใหม่ครบเกณฑ์จึงเปิดอีกครั้ง':'Scoped by machine, IP and detection period, not log type filters. Acknowledgement is not closure. Reopening requires a fresh threshold of evidence.'}}</p><p v-if="error" role="alert">{{error}}</p><p v-if="!rows.length&&!error">{{th?'ยังไม่มีเคสตามเงื่อนไข':'No matching cases'}}</p><article v-for="row in rows" :key="row.id"><strong>#{{row.id}} · {{row.agent}} · {{row.ip||'—'}} · {{row.actor||'—'}}</strong><p>{{ruleName(row.rule)}} · {{ui(row.status)}} · {{th?'หลักฐาน':'Evidence'}} #{{row.firstLogId}}–#{{row.lastLogId}}</p><p>{{row.explanation}}</p><button class="secondary" @click="journey(row.id)">{{th?'ดูลำดับหลักฐาน':'Evidence timeline'}}</button> <button v-if="canManage" class="secondary" @click="editing={...row};note=row.resolutionNote||'';owner=row.owner||''">{{th?'จัดการเคส':'Manage case'}}</button></article><section v-if="evidence" class="journey"><h3>{{th?'ลำดับหลักฐานเคส':'Case evidence timeline'}} #{{evidence.id}}</h3><p>{{th?'เรียงเหตุการณ์เครื่อง/IP เดียวกันตั้งแต่หลักฐานเคสถึงหนึ่งชั่วโมงหลังเหตุการณ์ตรวจพบล่าสุด ไม่ยืนยันว่าเป็นผู้กระทำคนเดียวหรือเป็นลำดับการเจาะระบบสำเร็จ':'Events from the same machine/IP from case evidence through one hour after the latest detection. This does not establish a single actor or a successful attack chain.'}}</p><ol><li v-for="e in evidence.events" :key="e.id"><strong>#{{e.id}} · {{e.event}}</strong> · {{e.occurredAt}} · {{e.actor||'—'}} · {{e.result||'—'}}<details><summary>{{th?'หลักฐานต้นฉบับ':'Original evidence'}}</summary><pre>{{e.detailsJson}}</pre></details></li></ol><p v-if="!evidence.events.length">{{th?'ไม่พบหลักฐาน อาจหมดอายุตามนโยบายเก็บข้อมูล':'No retained evidence; records may have expired under retention policy'}}</p><p v-if="evidence.truncated">{{th?'แสดง 200 รายการแรก ดู Log หรือ Export เพื่อดูเพิ่ม':'First 200 records shown; use logs or export for more'}}</p><button class="link" @click="evidence=null">{{th?'ปิดรายละเอียด':'Close details'}}</button></section><form v-if="editing" @submit.prevent="save('RESOLVED')"><h3>#{{editing.id}}</h3><label>{{th?'ผู้รับผิดชอบ':'Owner'}}<input v-model="owner" maxlength="150"></label><label>{{th?'ผลตรวจสอบและวิธีแก้ไข':'Investigation and remediation'}}<textarea v-model="note" maxlength="2000" required /></label><div><button type="button" class="secondary" :disabled="busy" @click="save('ACKNOWLEDGED')">{{th?'รับทราบ':'Acknowledge'}}</button> <button class="primary" :disabled="busy||!note.trim()">{{th?'ปิดเคส':'Resolve'}}</button> <button type="button" class="link" :disabled="busy" @click="editing=null">{{th?'ยกเลิก':'Cancel'}}</button></div></form><p v-if="truncated">{{th?'แสดง 200 เคสแรก กรุณากรองเพิ่ม':'First 200 cases shown; narrow filters'}}</p></details></template>
<style scoped>.threat-cases{padding:20px;margin-bottom:20px}.threat-cases summary{cursor:pointer;font-weight:600}.threat-cases p{color:#adbed3;font-size:13px;line-height:1.7;overflow-wrap:anywhere}.threat-cases article{padding:14px 0;border-top:1px solid #2b394e}.threat-cases form{padding:18px;border:1px solid #465973;border-radius:8px}.threat-cases label{margin-bottom:12px}.journey{padding:16px;border:1px solid #425775;border-radius:10px}.journey li{padding:12px;border-left:3px solid #58bca9;overflow-wrap:anywhere}.journey pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}</style>
